package com.aiuml.architect.project;
import com.aiuml.architect.diagram.DiagramRepository;
import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @Transactional(readOnly=true) public class ProjectService { private final ProjectRepository projects; private final ProjectMembershipRepository memberships; private final DiagramRepository diagrams; public ProjectService(ProjectRepository p,ProjectMembershipRepository m, DiagramRepository d){projects=p;memberships=m;diagrams=d;} public List<ProjectResponse> assigned(UUID userId){return memberships.findByUserId(userId).stream().map(m->{var p=projects.findById(m.projectId).orElseThrow(); return new ProjectResponse(p.id,p.name,p.description,m.role,(int) diagrams.countByProjectId(p.id));}).toList();} public void requireMember(UUID projectId,UUID userId){if(!memberships.existsByProjectIdAndUserId(projectId,userId))throw new AccessDeniedException();} public record ProjectResponse(UUID id,String name,String description,String role,int diagramCount){} public static class AccessDeniedException extends RuntimeException{} }
